import subprocess, json, os, datetime
p="/tmp/time1"
def probe(off):
    dt=datetime.datetime.now(datetime.timezone.utc)-datetime.timedelta(seconds=off)
    ds=dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    e=os.environ.copy(); e.update({"GIT_AUTHOR_DATE":ds,"GIT_COMMITTER_DATE":ds})
    subprocess.run("git commit -q --amend --no-edit",shell=True,cwd=p,capture_output=True,env=e)
    r=subprocess.run(["/workspace/executable","--output","json"],cwd=p,capture_output=True,text=True)
