    ("no-color-palette", None, "flag", None, None, None),
    ("no-art", None, "flag", None, None, None),
    ("nerd-fonts", None, "flag", None, None, None),
    ("output", "o", "single", "FORMAT", ["json","yaml"], "enum"),
    ("generate", None, "single", "SHELL", ["bash","elvish","fish","powershell","zsh"], "enum"),
    ("languages", "l", "flag", None, None, None),
    ("package-managers", "p", "flag", None, None, None),
]
SPEC_BY_LONG = {}
SPEC_BY_SHORT = {}
for _s in SPECS:
    _d = {"long": _s[0], "short": _s[1], "kind": _s[2], "metavar": _s[3], "possible": _s[4], "validator": _s[5]}
    if _s[2] == "flag":
        _d["err_name"] = f"--{_s[0]}"; _d["usage"] = f"--{_s[0]}"
    elif _s[2] == "optional":
        _d["err_name"] = f"--{_s[0]}[=<{_s[3]}>]"; _d["usage"] = f"--{_s[0]}[=<{_s[3]}>]"
    elif _s[2] == "multi":
        _d["err_name"] = f"--{_s[0]} <{_s[3]}>..."; _d["usage"] = f"--{_s[0]} <{_s[3]}>..."
    else:
        _d["err_name"] = f"--{_s[0]} <{_s[3]}>"; _d["usage"] = f"--{_s[0]} <{_s[3]}>"
    SPEC_BY_LONG[_s[0]] = _d
    if _s[1]: SPEC_BY_SHORT[_s[1]] = _d

def help_text(long_form):
    txt = TEXT_DATA["help_long" if long_form else "help_short"]
    return txt.replace("Usage: executable", f"Usage: {BIN}", 1)

def err_more():
    return "\nFor more information, try '--help'.\n"

def _jaro(s1, s2):
    if s1 == s2: return 1.0
    if not s1 or not s2: return 0.0
    match_dist = max(len(s1), len(s2)) // 2 - 1
    if match_dist < 0: match_dist = 0
    s1m = [False]*len(s1); s2m = [False]*len(s2); matches = 0
    for i,c in enumerate(s1):
        lo = max(0, i-match_dist); hi = min(len(s2), i+match_dist+1)
        for j in range(lo, hi):
            if not s2m[j] and s2[j] == c:
                s1m[i] = True; s2m[j] = True; matches += 1; break
    if matches == 0: return 0.0
    t = 0; k = 0
    for i in range(len(s1)):
        if s1m[i]:
            while not s2m[k]: k += 1
            if s1[i] != s2[k]: t += 1
            k += 1
    return (matches/len(s1) + matches/len(s2) + (matches - t//2)/matches) / 3

def _similar(name):
    best = None; bestv = 0.0
    for cand in list(SPEC_BY_LONG.keys()) + ["help", "version"]:
        # jaro-winkler
        j = _jaro(name, cand)
        p = 0
        for a,b in zip(name, cand):
            if a == b and p < 4: p += 1
            else: break
        jw = j + p*0.1*(1-j)
        if jw > bestv:
            bestv = jw; best = cand
    if bestv > 0.8:
        return best
    return None

def validate_value(spec, v):
    kind = spec["validator"]; en = spec["err_name"]
    if kind == "enum":
        if v not in spec["possible"]:
            poss = ", ".join(spec["possible"])
            raise ClapExit(2, stderr=f"error: invalid value '{v}' for '{en}'\n  [possible values: {poss}]\n{err_more()}")
        return v
    if kind == "usize":
        if v == "":
            msg = "cannot parse integer from empty string"
            raise ClapExit(2, stderr=f"error: invalid value '{v}' for '{en}': {msg}\n{err_more()}")
        if not re.fullmatch(r"\+?[0-9]+", v or ""):
            msg = "invalid digit found in string"
            raise ClapExit(2, stderr=f"error: invalid value '{v}' for '{en}': {msg}\n{err_more()}")
        n = int(v)
        if n > 18446744073709551615:
            msg = "number too large to fit in target type"
            raise ClapExit(2, stderr=f"error: invalid value '{v}' for '{en}': {msg}\n{err_more()}")
        return n
    if kind == "color":
        if v == "":
            msg = "cannot parse integer from empty string"
            raise ClapExit(2, stderr=f"error: invalid value '{v}' for '{en}': {msg}\n{err_more()}")
        if not re.fullmatch(r"[+-]?[0-9]+", v or ""):
            msg = "invalid digit found in string"
            raise ClapExit(2, stderr=f"error: invalid value '{v}' for '{en}': {msg}\n{err_more()}")
        n = int(v)
        if n > 9223372036854775807 or n < -9223372036854775808:
            msg = "number too large to fit in target type"
            raise ClapExit(2, stderr=f"error: invalid value '{v}' for '{en}': {msg}\n{err_more()}")
        if not (0 <= n < 16):
            raise ClapExit(2, stderr=f"error: invalid value '{v}' for '{en}': {v} is not in 0..16\n{err_more()}")
        return n
    if kind == "regex":
        try:
            re.compile(v)
        except re.error:
            # Rust-regex style error for common cases
            if v == "[" or (v.startswith("[") and "]" not in v):
                detail = f"regex parse error:\n    {v}\n    ^\nerror: unclosed character class"
            elif v == "(" or (v.count("(") > v.count(")")):
                detail = f"regex parse error:\n    {v}\n    ^\nerror: unclosed group"
            elif v in ("*", "+", "?"):
                detail = f"regex parse error:\n    {v}\n    ^\nerror: repetition operator missing expression"
            elif v.endswith("\\"):
                detail = f"regex parse error:\n    {v}\n    ^\nerror: incomplete escape sequence, reached end of pattern prematurely"
            else:
                detail = f"regex parse error:\n    {v}\n    ^\nerror: unclosed character class" if "[" in v else f"regex parse error:\n    {v}\n    ^\nerror: unclosed group"
