        self.input = None
    def mark(self, spec):
        if spec["usage"] not in self.used:
            self.used.append(spec["usage"])
    def get(self, name, default=None):
        return self.values.get(name, default)

def _unexpected(token, display, opts, is_positional=False, long_name=None):
    if is_positional:
        raise ClapExit(2, stderr=f"error: unexpected argument '{display}' found\n\nUsage: {BIN} [OPTIONS] [INPUT]\n{err_more()}")
    suggestion = None
    if long_name is not None:
        suggestion = _similar(long_name)
    if suggestion:
        if suggestion == "help":
            su = "--help"; 
        elif suggestion == "version":
            su = "--version"
        else:
            su = SPEC_BY_LONG[suggestion]["usage"]
        raise ClapExit(2, stderr=f"error: unexpected argument '{display}' found\n\n  tip: a similar argument exists: '--{suggestion}'\n\nUsage: {BIN} {su} [INPUT]\n{err_more()}")
    if opts.used:
        usage = " ".join(opts.used)
        raise ClapExit(2, stderr=f"error: unexpected argument '{display}' found\n\n  tip: to pass '{display}' as a value, use '-- {display}'\n\nUsage: {BIN} {usage} [INPUT]\n{err_more()}")
    raise ClapExit(2, stderr=f"error: unexpected argument '{display}' found\n\n  tip: to pass '{display}' as a value, use '-- {display}'\n\nUsage: {BIN} [OPTIONS] [INPUT]\n{err_more()}")

def _duplicate(spec):
    raise ClapExit(2, stderr=f"error: the argument '{spec['err_name']}' cannot be used multiple times\n\nUsage: {BIN} [OPTIONS] [INPUT]\n{err_more()}")

def _missing(spec):
    extra = ""
    if spec.get("possible"):
        extra = f"\n  [possible values: {', '.join(spec['possible'])}]"
    raise ClapExit(2, stderr=f"error: a value is required for '{spec['err_name']}' but none was supplied{extra}\n{err_more()}")

def _is_option_like(tok):
    return len(tok) > 1 and tok.startswith('-')

def _known_option_like(tok, opts):
    # determine if token would be parsed as a known option/help/version
    if tok.startswith('--'):
        name = tok[2:].split('=', 1)[0]
        return name in SPEC_BY_LONG or name in ('help', 'version')
    if tok.startswith('-') and len(tok) > 1:
        return tok[1] in SPEC_BY_SHORT or tok[1] in ('h', 'V')
    return False

def parse_args(argv):
    opts = Opts()
    # defaults later
    i = 0; end_opts = False
    while i < len(argv):
        tok = argv[i]
        if end_opts:
            if opts.input is not None:
                _unexpected(tok, tok, opts, is_positional=True)
            if tok == "":
                raise ClapExit(2, stderr=f"error: a value is required for '[INPUT]' but none was supplied\n{err_more()}")
            opts.input = tok; i += 1; continue
        if tok == "--":
            end_opts = True; i += 1; continue
        if tok.startswith("--") and tok != "--":
            body = tok[2:]
            if "=" in body:
                name, eqval = body.split("=", 1); has_eq = True
            else:
                name, eqval, has_eq = body, None, False
            display = "--" + name if name else "--"
            if name == "help" and not has_eq:
                raise ClapExit(0, stdout=help_text(True))
            if name == "version" and not has_eq:
                raise ClapExit(0, stdout=VERSION + "\n")
            if name in ("help", "version") and has_eq:
                # flag with value
                raise ClapExit(2, stderr=f"error: unexpected value '{eqval}' for '--{name}' found; no more were expected\n\nUsage: {BIN} --{name} [INPUT]\n{err_more()}")
            spec = SPEC_BY_LONG.get(name)
            if spec is None:
                _unexpected(tok, display, opts, long_name=name)
            # present
            kind = spec["kind"]
            if kind == "flag":
                if has_eq:
                    raise ClapExit(2, stderr=f"error: unexpected value '{eqval}' for '--{name}' found; no more were expected\n\nUsage: {BIN} --{name} [INPUT]\n{err_more()}")
                if name in opts.present: _duplicate(spec)
                opts.present.add(name); opts.explicit.add(name); opts.values[name] = True; opts.mark(spec); i += 1; continue
            if kind == "optional":
                if name in opts.present: _duplicate(spec)
                opts.present.add(name); opts.explicit.add(name); opts.mark(spec)
                if has_eq:
                    v = validate_value(spec, eqval) if eqval != "" else ""
                    opts.values[name] = v
                else:
                    opts.values[name] = None  # default pattern marker
                i += 1; continue
            # single / multi
            if kind == "single" and name in opts.present:
                _duplicate(spec)
            opts.present.add(name); opts.explicit.add(name); opts.mark(spec)
            collected = []
            if has_eq:
                collected.append(validate_value(spec, eqval))
                i += 1
            else:
                i += 1
                maxvals = 6 if name == "text-colors" else None
                while i < len(argv):
                    nt = argv[i]
                    if _is_option_like(nt):
                        break
                    if kind == "single" and collected: break
                    if maxvals is not None and len(collected) >= maxvals: break
                    collected.append(validate_value(spec, nt)); i += 1
                    if kind == "single": break
                if not collected:
                    # peek: if next token is unknown option-like, clap reports it as unexpected
                    if i < len(argv) and _is_option_like(argv[i]) and not _known_option_like(argv[i], opts):
                        nt = argv[i]
                        if nt.startswith("--"):
                            dn = "--" + nt[2:].split("=",1)[0]
                            _unexpected(nt, dn, opts, long_name=nt[2:].split("=",1)[0])
                        else:
                            _unexpected(nt, nt[:2], opts)
                    _missing(spec)
            if kind == "multi":
                opts.values.setdefault(name, []).extend(collected)
            else:
                opts.values[name] = collected[0]
            continue
        if tok.startswith("-") and tok != "-":
            # short cluster
            chars = tok[1:]
            j = 0; consumed_next = False
            while j < len(chars):
                ch = chars[j]
                if ch == 'h':
                    raise ClapExit(0, stdout=help_text(False))
                if ch == 'V':
                    raise ClapExit(0, stdout=VERSION + "\n")
                spec = SPEC_BY_SHORT.get(ch)
                if spec is None:
                    _unexpected(tok, f"-{ch}", opts)
                name = spec["long"]; kind = spec["kind"]
                if kind == "flag":
                    if name in opts.present: _duplicate(spec)
                    opts.present.add(name); opts.explicit.add(name); opts.values[name] = True; opts.mark(spec); j += 1; continue
                # value option: rest of cluster is attached value if present
                if name in opts.present and kind == "single": _duplicate(spec)
                opts.present.add(name); opts.explicit.add(name); opts.mark(spec)
                rest = chars[j+1:]
                collected = []
                if rest:
                    if rest.startswith("="): rest = rest[1:]
                    collected.append(validate_value(spec, rest))
                    j = len(chars)
                else:
                    i += 1; consumed_next = True
                    maxvals = 6 if name == "text-colors" else None
                    while i < len(argv):
                        nt = argv[i]
                        if _is_option_like(nt): break
                        if kind == "single" and collected: break
                        if maxvals is not None and len(collected) >= maxvals: break
                        collected.append(validate_value(spec, nt)); i += 1
                        if kind == "single": break
                    if not collected:
                        if i < len(argv) and _is_option_like(argv[i]) and not _known_option_like(argv[i], opts):
                            nt = argv[i]
                            if nt.startswith("--"):
                                dn = "--" + nt[2:].split("=",1)[0]
                                _unexpected(nt, dn, opts, long_name=nt[2:].split("=",1)[0])
                            else:
                                _unexpected(nt, nt[:2], opts)
