COMMENT_SPECS = {
    'none': ([], []),
    'hash': (['#'], []),
    'abap': (['"'], []),
    'dash': (['--'], []),
    'dashblock': (['--'], [('{-', '-}')]),
    'ocaml': ([], [('(*', '*)')]),
    'ocamlslash': (['//'], [('(*', '*)')]),
    'c': (['//'], [('/*', '*/')]),
