    'pascal': (['//'], [('{', '}'), ('(*', '*)')]),
    'slashdoc': (['//'], []),
    'quote': (["'"], []),
    'vim': (['"'], []),
    'wat': ([';;'], [('(;', ';)')]),
    'dashblocksql': (['--'], [('/*', '*/')]),
    'jupyter': ([], []),
}
NESTED_SLUGS = {'rust', 'kotlin', 'swift', 'ocaml', 'f#', 'scala'}

def count_code_lines(text, slug):
    specname = LANG_DEFS.get(slug, {}).get('comments', 'none')
    if specname == 'jupyter':
        return 0
    line_tokens, block_pairs = COMMENT_SPECS.get(specname, ([], []))
    if not line_tokens and not block_pairs:
        return sum(1 for line in text.splitlines() if line.strip())
    nested = slug in NESTED_SLUGS
    code = 0
    in_block = None  # (start,end)
    block_depth = 0
    for raw in text.splitlines():
        line = raw
        if in_block is None and not line.strip():
            continue
        if in_block is not None:
            start_tok, end_tok = in_block
            pos = 0
            while True:
                end_i = line.find(end_tok, pos)
                if nested:
                    start_i = line.find(start_tok, pos)
                    if start_i != -1 and (end_i == -1 or start_i < end_i):
                        block_depth += 1; pos = start_i + len(start_tok); continue
                if end_i == -1:
                    break
                if nested and block_depth > 1:
                    block_depth -= 1; pos = end_i + len(end_tok); continue
                in_block = None; block_depth = 0
                pos = end_i + len(end_tok)
                # If another block starts in remainder, enter it; line remains a comment line
                entered = False
                for s, e in block_pairs:
                    si = line.find(s, pos)
                    if si != -1:
                        in_block = (s, e); block_depth = 1; entered = True; break
                break
            continue
        # not in block
        pos = 0; has_code = False
        while pos <= len(line):
            # find earliest token
            best_idx = None; best_kind = None; best_pair = None
            for tok in line_tokens:
                idx = line.find(tok, pos)
                if idx != -1 and (best_idx is None or idx < best_idx):
                    best_idx = idx; best_kind = 'line'; best_pair = None
            for s, e in block_pairs:
                idx = line.find(s, pos)
                if idx != -1 and (best_idx is None or idx < best_idx):
                    best_idx = idx; best_kind = 'block'; best_pair = (s, e)
            if best_idx is None:
                if line[pos:].strip(): has_code = True
                break
            if line[pos:best_idx].strip():
                has_code = True
            if best_kind == 'line':
                break
            # block
            s, e = best_pair
            end_i = line.find(e, best_idx + len(s))
            if end_i == -1:
                in_block = (s, e); block_depth = 1
                break
            else:
                if nested:
                    # crude nested handling within one line
                    depth = 1; scan = best_idx + len(s)
                    while True:
                        ni = line.find(s, scan); ei = line.find(e, scan)
                        if ei == -1:
                            in_block = (s, e); block_depth = depth; break
                        if ni != -1 and ni < ei:
                            depth += 1; scan = ni + len(s)
                        else:
                            depth -= 1; scan = ei + len(e)
                            if depth == 0:
                                break
                    if in_block is not None:
                        break
                    pos = scan; continue
                pos = end_i + len(e); continue
        if has_code:
            code += 1
    return code

def count_notebook(content):
    try:
        data = json.loads(content)
    except Exception:
        return 0
    if not isinstance(data, dict):
        return 0
    total = 0
    for cell in data.get("cells", []) if isinstance(data.get("cells", []), list) else []:
        if not isinstance(cell, dict) or cell.get("cell_type") != "code":
            continue
        src = cell.get("source", "")
        if isinstance(src, list):
            total += len(src)
        elif isinstance(src, str):
            total += len(src.splitlines())
    return total

# ignore handling
def _glob_to_regex(pat):
    i = 0; out = ""
    while i < len(pat):
        c = pat[i]
        if c == '*':
            if pat[i:i+2] == '**':
                if pat[i:i+3] == '**/':
                    out += '(?:.*/)?'; i += 3
                else:
                    out += '.*'; i += 2
            else:
                out += '[^/]*'; i += 1
        elif c == '?':
            out += '[^/]'; i += 1
        elif c == '[':
            j = i + 1
            if j < len(pat) and pat[j] in '!^': j += 1
            if j < len(pat) and pat[j] == ']': j += 1
            while j < len(pat) and pat[j] != ']': j += 1
            if j >= len(pat):
                out += '\\['; i += 1
            else:
                stuff = pat[i+1:j]
                if stuff.startswith('!'): stuff = '^' + stuff[1:]
                out += '[' + stuff + ']'; i = j + 1
        else:
            out += re.escape(c); i += 1
    return out

class IgnoreRule:
    def __init__(self, base, pattern):
        self.base = base  # relative dir (posix, '' for root)
        self.neg = False
        p = pattern
        if p.startswith('!'):
            self.neg = True; p = p[1:]
        elif p.startswith('\\!') or p.startswith('\\#'):
            p = p[1:]
        self.dir_only = p.endswith('/')
        if self.dir_only: p = p[:-1]
        self.anchored = '/' in p
        if p.startswith('/'): p = p[1:]
        self.pattern = p
        try:
            self.regex = re.compile('^' + _glob_to_regex(p) + '$')
        except Exception:
            self.regex = None
    def matches(self, rel_to_base, is_dir):
        if self.regex is None or not self.pattern:
            return False
        if self.dir_only and not is_dir:
            # a dir-only pattern can still exclude files under a matched directory; caller checks parents
            pass
        candidates = [rel_to_base]
        parts = rel_to_base.split('/')
        # parent directories
        for i in range(1, len(parts)):
            candidates.append('/'.join(parts[:i]))
        targets = []
        for cand in candidates:
            is_parent = cand != rel_to_base
            if self.anchored:
                targets.append(cand)
            else:
                targets.append(cand.split('/')[-1])
                targets.append(cand)
        for t in targets:
            if self.regex.match(t):
                return True
        return False

def load_ignore_rules(dir_abs, base_rel):
    rules = []
    for fname in ('.gitignore', '.ignore', '.tokeignore'):
        fp = os.path.join(dir_abs, fname)
        if os.path.isfile(fp) and not os.path.islink(fp):
            try:
                with open(fp, 'r', encoding='utf-8', errors='replace') as f:
                    for raw in f:
                        line = raw.rstrip('\n').rstrip('\r')
                        if not line.strip() or line.lstrip().startswith('#'):
                            continue
                        line = line.rstrip()
                        rules.append(IgnoreRule(base_rel, line))
            except Exception:
                pass
    return rules

def is_ignored(rel_posix, is_dir, rules_stack):
    ignored = False
    for base, rules in rules_stack:
        if base:
            if rel_posix == base: rel = ''
            elif rel_posix.startswith(base + '/'): rel = rel_posix[len(base)+1:]
            else: continue
        else:
            rel = rel_posix
        if not rel: continue
        for rule in rules:
            if rule.matches(rel, is_dir):
                ignored = not rule.neg
    return ignored

def collect_languages(root, opts):
    exclude_patterns = opts.get("exclude", []) or []
    exclude_rules = [IgnoreRule('', p) for p in exclude_patterns]
    include_hidden = bool(opts.get("include-hidden"))
    counts = {}
    # walk
    for dirpath, dirnames, filenames in os.walk(root, topdown=True, followlinks=False):
        rel_dir = os.path.relpath(dirpath, root)
        rel_dir_posix = '' if rel_dir == '.' else rel_dir.replace(os.sep, '/')
        # load rules for this dir (including root); store on stack via attribute on dirpath traversal:
        # os.walk doesn't carry state, so recompute by gathering rules from ancestors
        rules_stack = []
        # ancestor chain
        chain = [''] if not rel_dir_posix else [''] + ['/'.join(rel_dir_posix.split('/')[:i+1]) for i in range(len(rel_dir_posix.split('/')))]
        for base in chain:
            abs_base = os.path.join(root, base) if base else root
            rules_stack.append((base, load_ignore_rules(abs_base, base)))
        # prune dirs
        keep_dirs = []
        for d in list(dirnames):
            full = os.path.join(dirpath, d)
            rel = (rel_dir_posix + '/' + d) if rel_dir_posix else d
            if d == '.git': continue
            if os.path.islink(full): continue
            if not include_hidden and d.startswith('.'): continue
            if is_ignored(rel, True, rules_stack): continue
            if any(r.matches(rel, True) for r in exclude_rules): continue
            keep_dirs.append(d)
        dirnames[:] = keep_dirs
        for fname in filenames:
            full = os.path.join(dirpath, fname)
            rel = (rel_dir_posix + '/' + fname) if rel_dir_posix else fname
            if os.path.islink(full): continue
            if not os.path.isfile(full): continue
            if not include_hidden and fname.startswith('.'): continue
            if is_ignored(rel, False, rules_stack): continue
            if any(r.matches(rel, False) for r in exclude_rules): continue
            slug = None
            if fname in FILENAME_MAP:
                slug = FILENAME_MAP[fname]
            elif fname.lower() in FILENAME_MAP:
                slug = FILENAME_MAP[fname.lower()]
            else:
                # extension
                if '.' in fname and not (fname.startswith('.') and fname.count('.') == 1):
                    ext = fname.rsplit('.', 1)[1].lower()
                    slug = EXT_MAP.get(ext)
                if slug is None:
                    # shebang for extensionless/no-dot files
                    if '.' not in fname:
                        try:
                            with open(full, 'rb') as f:
                                first = f.readline().decode('utf-8', 'replace').strip()
                            slug = SHEBANG_MAP.get(first)
                        except Exception:
                            slug = None
            if slug is None: continue
            try:
                with open(full, 'rb') as f:
                    raw = f.read()
            except Exception:
                continue
            text = raw.decode('utf-8', 'replace')
            if LANG_DEFS[slug].get('comments') == 'jupyter':
                c = count_notebook(text)
            else:
                c = count_code_lines(text, slug)
            if c:
                counts[slug] = counts.get(slug, 0) + c
    types = set(opts.get("type", ["programming", "markup"]) or [])
    filtered = {s: c for s, c in counts.items() if LANG_DEFS[s]['type'] in types}
    total = sum(filtered.values())
    langs = []
    if total:
        for slug, c in filtered.items():
            langs.append({"slug": slug, "language": LANG_DEFS[slug]['json'], "display": LANG_DEFS[slug]['display'], "count": c, "percentage": c / total * 100.0})
        langs.sort(key=lambda x: (-x["count"], x["display"].encode()))
    return langs, total
