# ---------------------------------------------------------------- git helpers

def git(root, args, input_data=None):
    try:
        r = subprocess.run(["git", "-C", root] + args, capture_output=True, input=input_data, timeout=30)
    except Exception:
        return 1, b"", b""
    return r.returncode, r.stdout, r.stderr

def git_text(root, args):
    rc, out, _ = git(root, args)
    if rc != 0:
        return None
    return out.decode("utf-8", "replace")

def find_repo_root(input_abs):
    p = os.path.normpath(input_abs)
    cur = p
    while True:
        base = os.path.basename(cur)
        if base == ".git" and os.path.isdir(cur) and os.path.exists(os.path.join(cur, "HEAD")):
            return os.path.dirname(cur)
        if os.path.exists(os.path.join(cur, ".git")):
            return cur
        parent = os.path.dirname(cur)
        if parent == cur:
            return None
        cur = parent

def repo_git_dir(root):
    txt = git_text(root, ["rev-parse", "--git-dir"])
    if not txt:
        return os.path.join(root, ".git")
    gd = txt.strip().splitlines()[0]
    if not os.path.isabs(gd):
        gd = os.path.normpath(os.path.join(root, gd))
    return gd

def read_commits(root):
    # HEAD ref for error message
    rc, out, _ = git(root, ["log", "--format=%H%x1f%P%x1f%an%x1f%ae%x1f%ct%x1e", "HEAD"])
    if rc != 0 or not out.strip():
        # determine branch ref
        ref = None
        txt = git_text(root, ["symbolic-ref", "-q", "HEAD"])
        if txt:
            ref = txt.strip()
        if not ref:
            try:
                gd = repo_git_dir(root)
                with open(os.path.join(gd, "HEAD"), "r", encoding="utf-8", "replace") as f:
                    content = f.read().strip()
                if content.startswith("ref:"):
                    ref = content[4:].strip()
            except Exception:
                pass
        if not ref:
            ref = "refs/heads/master"
        raise AppError(f"Error: Failed to traverse Git commit history\n\nCaused by:\n    Branch '{ref}' does not have any commits\n")
    commits = []
    for rec in out.decode("utf-8", "replace").split("\x1e"):
        rec = rec.strip("\n")
        if not rec.strip():
            continue
        parts = rec.split("\x1f")
        if len(parts) < 5:
            continue
        h, parents, an, ae, ct = parts[:5]
        try: epoch = int(ct)
        except Exception: epoch = 0
        commits.append({"hash": h, "parents": parents.split() if parents.strip() else [], "name": an, "email": ae, "time": epoch})
    if not commits:
        ref = "refs/heads/master"
        raise AppError(f"Error: Failed to traverse Git commit history\n\nCaused by:\n    Branch '{ref}' does not have any commits\n")
    return commits

def human_time(ts, now):
    delta = now - ts
    future = delta < 0
    a = abs(delta)
    if a <= 10:
        return "now"
    if a <= 45:
        phrase = f"{a} seconds"
    elif a <= 90:
        phrase = "a minute"
    elif a <= 2700:
        phrase = f"{max(2, a//60)} minutes"
    elif a <= 5400:
        phrase = "an hour"
    elif a <= 79200:
        phrase = f"{max(2, a//3600)} hours"
    elif a <= 129600:
        phrase = "a day"
    elif a <= 561600:
        phrase = f"{max(2, a//86400)} days"
    elif a <= 907200:
        phrase = "a week"
    elif a < 2592000:
        phrase = f"{max(2, a//604800)} weeks"
    elif a <= 3888000:
        phrase = "a month"
    elif a <= 29808000:
        phrase = f"{max(2, a//2592000)} months"
    elif a < 47304000:
        phrase = "a year"
    else:
        phrase = f"{max(2, a//31536000)} years"
    return f"in {phrase}" if future else f"{phrase} ago"

def iso_time(ts):
    dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def fmt_num(n, opts):
    sepname = opts.get("number-separator", "plain")
    if sepname == "plain" or n is None:
        return str(n)
    sep = {"comma": ",", "space": " ", "underscore": "_"}[sepname]
    s = str(abs(n)); parts = []
    while len(s) > 3:
        parts.append(s[-3:]); s = s[:-3]
    parts.append(s)
    return ("-" if n < 0 else "") + sep.join(reversed(parts))

def human_size(num):
    if num < 1024:
        return f"{num} B"
    units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"]
    val = float(num); idx = 0
    while val >= 1024 and idx < len(units) - 1:
        val /= 1024.0; idx += 1
    txt = f"{val:.2f}".rstrip("0").rstrip(".")
    return f"{txt} {units[idx]}"

# ---------------------------------------------------------------- manifests

def parse_cargo_toml(path):
    try:
        with open(path, "rb") as f:
            data = f.read()
    except Exception:
        return None
    parsed = None
    try:
        try:
            import tomllib
        except ImportError:
            import tomli as tomllib
        parsed = tomllib.loads(data.decode("utf-8", "replace"))
    except Exception:
        return None
    if not isinstance(parsed, dict):
        return None
    pkg = parsed.get("package")
    if not isinstance(pkg, dict):
        return None
    name = pkg.get("name")
    if not isinstance(name, str):
        return None
    version = pkg.get("version", "0.0.0")
    if not isinstance(version, str):
        return None
    desc = pkg.get("description")
    if desc is not None and not isinstance(desc, str):
        return None
    lic = pkg.get("license")
    if lic is not None and not isinstance(lic, str):
        return None
    deps = parsed.get("dependencies")
    if deps is None:
        count = 0
    elif isinstance(deps, dict):
        count = len(deps)
    else:
        return None
    return {"manager": "Cargo", "version": version, "description": desc, "license": lic, "dep_count": count}

def parse_package_json(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            parsed = json.load(f)
    except Exception:
        return None
    if not isinstance(parsed, dict):
        return None
    if not isinstance(parsed.get("name"), str) or not isinstance(parsed.get("version"), str):
        return None
    desc = parsed.get("description")
    if desc is not None and not isinstance(desc, str):
        return None
    lic = parsed.get("license")
    if lic is not None and not isinstance(lic, str):
        return None
    if "dependencies" in parsed:
        deps = parsed.get("dependencies")
        if not isinstance(deps, dict):
            return None
        # serde map of string->string: values should be strings
        if any(not isinstance(v, str) for v in deps.values()):
            return None
        count = len(deps)
    else:
        count = 0
    return {"manager": "Npm", "version": parsed.get("version"), "description": desc, "license": lic, "dep_count": count}

def get_manifests(root):
    out = []
    pj = os.path.join(root, "package.json")
    if os.path.isfile(pj):
        m = parse_package_json(pj)
        if m: out.append(m)
    ct = os.path.join(root, "Cargo.toml")
    if os.path.isfile(ct):
        m = parse_cargo_toml(ct)
        if m: out.append(m)
    return out

