COMMENT_SPECS = {
    'none': ([], []),
    'hash': (['#'], []),
    'abap': (['"'], []),
    'dash': (['--'], []),
    'dashblock': (['--'], [('{-', '-}')]),
    'ocaml': ([], [('(*', '*)')]),
    'ocamlslash': (['//'], [('(*', '*)')]),
    'c': (['//'], [('/*', '*/')]),
    'css': ([], [('/*', '*/')]),
    'html': ([], [('<!--', '-->')]),
    'semi': ([';'], []),
    'percent': (['%'], []),
    'percentblock': (['%'], [('/*', '*/')]),
    'bang': (['!'], []),
    'forth': (['\\'], []),
    'hcl': (['#', '//'], [('/*', '*/')]),
    'chash': (['//', '#'], [('/*', '*/')]),
    'hashblock': (['#'], [('#=', '=#')]),
