def detect_license_text(content):
    low = re.sub(r"\s+", " ", content.lower())
    # Order matters: LGPL/GPL before generic etc.
    checks = [
        ("LGPL-2.1-only", "gnu lesser general public license" in low and "version 2.1" in low),
        ("LGPL-3.0-only", "gnu lesser general public license" in low and "version 3" in low),
        ("LGPL-2.0-only", ("gnu lesser general public license" in low or "gnu library general public license" in low) and "version 2" in low),
        ("GPL-3.0-only", "gnu general public license" in low and "version 3" in low),
        ("GPL-2.0-only", "gnu general public license" in low and "version 2" in low),
        ("GPL-1.0-only", "gnu general public license" in low and "version 1" in low),
        ("AGPL-3.0-only", "gnu affero general public license" in low and "version 3" in low),
        ("Apache-2.0", "apache license" in low and "version 2.0" in low),
        ("MPL-2.0", "mozilla public license" in low and "2.0" in low),
        ("MPL-1.1", "mozilla public license" in low and "1.1" in low),
        ("CC0-1.0", "cc0 1.0" in low),
        ("Unlicense", "unencumbered software released into the public domain" in low or low.strip().startswith("this is free and unencumbered")),
        ("MIT", "permission is hereby granted, free of charge" in low and "mit license" in low or ("permission is hereby granted, free of charge, to any person obtaining a copy" in low and "the software" in low and "deal in the software without restriction" in low)),
        ("BSD-3-Clause", "redistribution and use in source and binary forms" in low and "neither the name" in low),
        ("BSD-2-Clause", "redistribution and use in source and binary forms" in low),
        ("ISC", "permission to use, copy, modify, and/or distribute this software" in low),
        ("Artistic-1.0-Perl", "artistic license" in low),
        ("GFDL-1.3-invariants-only", "gnu free documentation license" in low and "1.3" in low),
        ("Zlib", "zlib" in low and "altered source versions must be plainly marked" in low),
    ]
    for name, ok in checks:
        if ok:
            return name
    return None

def get_license(root, manifests):
    if manifests:
        lic = manifests[0].get("license")
        if lic:
            return lic
    found = []
    try:
        entries = sorted(os.listdir(root))
    except Exception:
        entries = []
    for name in entries:
        full = os.path.join(root, name)
        if not os.path.isfile(full):
            continue
        if not (name.startswith("LICENSE") or name.startswith("LICENCE") or name.startswith("COPYING")):
            continue
        try:
            with open(full, "r", encoding="utf-8", errors="replace") as f:
                content = f.read()
        except Exception:
            continue
        lic = detect_license_text(content)
        if lic and lic not in found:
            found.append(lic)
    return ", ".join(sorted(found))

