# ---------------------------------------------------------------- URL helpers

def redact_and_transform(url, opts):
    display = url
    # token handling for canonical scheme URLs
    def split_authority(u):
        m = re.match(r'^([A-Za-z][A-Za-z0-9+.-]*://)([^/]*)(.*)$', u, re.DOTALL)
        if not m: return None
        return m.group(1), m.group(2), m.group(3)
    parts = split_authority(display)
    if opts.get("hide-token"):
        if parts and '@' in parts[1]:
            auth = parts[1].rsplit('@', 1)[1]
            display = parts[0] + auth + parts[2]
    else:
        parts = split_authority(display)
        if parts and '@' in parts[1]:
            userinfo, auth = parts[1].rsplit('@', 1)
            if ':' in userinfo:
                user = userinfo.split(':', 1)[0]
                userinfo = user + ':redacted'
                display = parts[0] + userinfo + '@' + auth + parts[2]
    if opts.get("http-url"):
        m = re.match(r'^(?:[^@]*@)([^/:]+):(.*)$', display, re.DOTALL)
        if m:
            display = f"https://{m.group(1)}/{m.group(2)}"
            # hide-token with an http-converted SCP style URL keeps https host form; userinfo gone already
    return display

def repo_name_from_url(url):
    if not url:
        return ""
    path = url
    if '://' in url:
        rest = url.split('://', 1)[1]
        if '/' in rest:
            path = rest.split('/', 1)[1]
        else:
            path = ''
    else:
        m = re.match(r'^(?:[^@]*@)([^/:]+):(.*)$', url, re.DOTALL)
        if m:
            path = m.group(2)
        else:
            path = url
    path = path.rstrip('/')
    if not path:
        return ""
    base = path.rsplit('/', 1)[-1]
    if not base:
        return ""
    if base.startswith('.') and base.count('.') == 1:
        return base
    if '.' in base:
        return base.rsplit('.', 1)[0]
    return base

