    username = (git_text(root, ["config", "--get", "user.name"]) or "").strip("\n")
    # strip only trailing newline effect: git_text already removed? username may have trailing spaces intentional? keep strip of newline only
    git_version = ""
    try:
        r = subprocess.run(["git", "--version"], capture_output=True)
        git_version = r.stdout.decode("utf-8", "replace").strip()
    except Exception:
        git_version = "git version 2.34.1"
    now = int(time.time())
    def date_str(ts):
        return iso_time(ts) if opts.get("iso-time") else human_time(ts, now)
    created = date_str(commits_all[-1]["time"])
    last_change = date_str(commits_all[0]["time"])
    is_shallow_txt = git_text(root, ["rev-parse", "--is-shallow-repository"])
    is_shallow = bool(is_shallow_txt and is_shallow_txt.strip() == "true")
    info = {
        "title": None if opts.get("no-title") else {"gitUsername": username, "gitVersion": git_version},
        "_username": username, "_git_version": git_version,
