        "languages": langs, "_loc": loc,
        "dependencies": {"dependencies": dependencies},
        "authors": authors_disp, "_total_authors": len(groups),
        "last_change": {"lastChange": last_change},
        "contributors": {"totalNumberOfAuthors": len(groups)},
        "url": {"repoUrl": repo_url},
        "commits": {"numberOfCommits": total_commits, "isShallow": is_shallow},
        "churn": {"file_churns": churn_disp, "churn_pool_size": len(pool_commits)},
        "size": {"repoSize": human_size(total_size), "fileCount": file_count},
        "license": {"license": lic},
        "_dominant_slug": langs[0]["slug"] if langs else None,
