def repo_name_from_url(url):
    if not url:
        return ""
    path = url
    if '://' in url:
        rest = url.split('://', 1)[1]
        if '/' in rest:
            path = rest.split('/', 1)[1]
        else:
            path = ''
    else:
        m = re.match(r'^(?:[^@]*@)([^/:]+):(.*)$', url, re.DOTALL)
        if m:
            path = m.group(2)
        else:
            path = url
    path = path.rstrip('/')
    if not path:
        return ""
    base = path.rsplit('/', 1)[-1]
    if not base:
        return ""
    if base.startswith('.') and base.count('.') == 1:
        return base
    if '.' in base:
        return base.rsplit('.', 1)[0]
