    churn_list = [{"filePath": p, "nbrOfCommits": n} for p, n in churn_counts.items()]
    churn_list.sort(key=lambda x: (-x["nbrOfCommits"], x["filePath"]))
    churn_disp = churn_list[:opts.get("number-of-file-churns", 3)]
    # languages
    langs, loc = collect_languages(root, opts)
    # size from index
    file_count = 0; total_size = 0
    rc, out, _ = git(root, ["ls-files", "--stage", "-z"])
    oids = []
    if rc == 0:
        for ent in out.decode("utf-8", "surrogateescape").split('\0'):
            if not ent: continue
            meta = ent.split('\t', 1)[0].split()
