        fields.append({jname: val})
    return {"title": info["title"], "infoFields": fields}

# ---------------------------------------------------------------- YAML emitter

def _yaml_needs_quote(s):
    if s == "": return True
    if s.strip() != s: return True
    if s in ("~", "null", "Null", "NULL", "true", "True", "TRUE", "false", "False", "FALSE", ".nan", ".NaN", ".NAN", ".inf", ".Inf", ".INF", "-.inf", "-.Inf", "-.INF"): return True
    # numeric lookalikes
    if re.fullmatch(r"[-+]?([0-9][0-9_]*)(\.[0-9_]*)?([eE][-+][0-9]+)?", s) and re.search(r"[0-9]", s):
        # plain integers/decimals that would be parsed as numbers
        if re.fullmatch(r"[-+]?(0|[1-9][0-9_]*|0[0-9_]+)(\.[0-9_]*)?([eE][-+][0-9]+)?", s): return True
    if re.fullmatch(r"[-+]?\.[0-9]+([eE][-+][0-9]+)?", s): return True
    if ": " in s or s.endswith(":"): return True
    if " #" in s or s.startswith("#"): return True
    if s[0] in "!&*[]{},|>@`%'\"#": return True
    if s[0] in "-?:" and (len(s) == 1 or s[1] == ' '): return True
    if s in ("-", "?", ":", "...", "---"): return True
    if any(ord(c) < 0x20 and c not in "\n" for c in s): return True
    if "[" in s or "]" in s or "{" in s or "}" in s: 
        # libyaml quotes flow indicators at start mainly; mid-string plain brackets are usually plain
        if s[0] in "[{": return True
    return False

def yaml_scalar(v):
    if v is None: return "null"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, float):
        if v == int(v) and abs(v) < 1e15: return f"{v:.1f}"
        return repr(v)
    s = str(v)
    if "\n" in s:
        return None  # handled by caller as block
    if _yaml_needs_quote(s):
        return "'" + s.replace("'", "''") + "'"
    return s

def yaml_emit(value, indent):
    lines = []
    pad = " " * indent
    if isinstance(value, dict):
        if not value: return [pad + "{}"]
        for k, v in value.items():
            key = str(k)
            if isinstance(v, dict):
                if not v: lines.append(f"{pad}{key}: {{}}")
                else:
                    lines.append(f"{pad}{key}:")
                    lines.extend(yaml_emit(v, indent + 2))
            elif isinstance(v, list):
                if not v: lines.append(f"{pad}{key}: []")
                else:
                    lines.append(f"{pad}{key}:")
                    lines.extend(yaml_emit(v, indent))
            elif isinstance(v, str) and "\n" in v:
                # block scalar
                trailing = len(v) - len(v.rstrip("\n"))
                header = "|-" if trailing == 0 else ("|" if trailing == 1 else "|+")
                lines.append(f"{pad}{key}: {header}")
                body = v.rstrip("\n") if trailing else v
                for bl in v.rstrip("\n").split("\n") if v.rstrip("\n") else [""]:
                    lines.append(" " * (indent + 2) + bl)
            else:
                lines.append(f"{pad}{key}: {yaml_scalar(v)}")
        return lines
    if isinstance(value, list):
        if not value: return [pad + "[]"]
        for item in value:
            if isinstance(item, dict):
                if not item: lines.append(f"{pad}- {{}}"); continue
                first = True
                for k, v in item.items():
                    prefix = f"{pad}- " if first else " " * (indent + 2)
                    key = str(k)
                    if isinstance(v, dict):
                        if not v: lines.append(f"{prefix}{key}: {{}}")
                        else:
                            lines.append(f"{prefix}{key}:")
                            lines.extend(yaml_emit(v, indent + 4))
                    elif isinstance(v, list):
                        if not v: lines.append(f"{prefix}{key}: []")
                        else:
                            lines.append(f"{prefix}{key}:")
                            lines.extend(yaml_emit(v, indent + 2))
                    elif isinstance(v, str) and "\n" in v:
                        trailing = len(v) - len(v.rstrip("\n"))
                        header = "|-" if trailing == 0 else ("|" if trailing == 1 else "|+")
                        lines.append(f"{prefix}{key}: {header}")
                        for bl in v.rstrip("\n").split("\n") if v.rstrip("\n") else [""]:
                            lines.append(" " * (indent + 4) + bl)
                    else:
                        lines.append(f"{prefix}{key}: {yaml_scalar(v)}")
                    first = False
            elif isinstance(item, list):
                lines.append(f"{pad}-")
                lines.extend(yaml_emit(item, indent + 2))
            else:
                if isinstance(item, str) and "\n" in item:
                    trailing = len(item) - len(item.rstrip("\n"))
                    header = "|-" if trailing == 0 else ("|" if trailing == 1 else "|+")
                    lines.append(f"{pad}- {header}")
                    for bl in item.rstrip("\n").split("\n") if item.rstrip("\n") else [""]:
                        lines.append(" " * (indent + 2) + bl)
                else:
                    lines.append(f"{pad}- {yaml_scalar(item)}")
        return lines
    return [pad + str(yaml_scalar(value))]

