# ---------------------------------------------------------------- text rendering

ANSI_FG = [30,31,32,33,34,35,36,37,90,91,92,93,94,95,96,97]

def strip_bold(spec):
    # spec like '34;1' or '38;2;1;2;3;1' or '34'
    if spec.endswith(";1"):
        return spec[:-2]
    return spec

def style_param(base, bold_elem, opts):
    if bold_elem and not opts.get("no-bold"):
        return base + ";1" if base else "39;1"
    return base

def ansi_user_base(v):
    return str(ANSI_FG[v])

class Palette:
    def __init__(self, info, opts):
        self.opts = opts
        self.true_color = self._true_color()
        self.text_colors = opts.get("text-colors", []) or []
        self.ascii_colors = opts.get("ascii-colors", []) or []
        self.dominant = info.get("_dominant_slug")
        self.art_slug = None
        if self.dominant:
            self.art_slug = opts.get("ascii-language") or self.dominant
        # primary base
        self.primary_base = "37"
        if self.ascii_colors:
            self.primary_base = ansi_user_base(self.ascii_colors[0])
        elif self.art_slug:
            c = self.token_color_base(0, self.art_slug)
            if c: self.primary_base = c
    def _true_color(self):
        w = self.opts.get("true-color", "auto")
        if w == "always": return True
        if w == "never": return False
        return os.environ.get("COLORTERM") in ("truecolor", "24bit")
    def token_color_base(self, token, slug):
        if slug is None: return "39"
        data = ART_DATA.get(slug)
        if not data: return "39"
        if self.true_color:
            spec = data.get("rgbColors", {}).get(str(token))
        else:
            spec = data.get("ansiColors", {}).get(str(token))
        if spec is None:
            return "39"
        return strip_bold(spec)
    def base_for(self, idx, default_base):
        if idx < len(self.text_colors):
            return ansi_user_base(self.text_colors[idx])
        return default_base
    def title_base(self):
        if self.text_colors: return ansi_user_base(self.text_colors[0])
        return self.primary_base
    def subtitle_base(self):
        if len(self.text_colors) > 3: return ansi_user_base(self.text_colors[3])
        return self.primary_base if not self.text_colors else (ansi_user_base(self.text_colors[3]) if len(self.text_colors)>3 else self.primary_base)
    # The subtitle default is the primary colour even when text-colors supplied for earlier slots

