                current = root; continue
            m = re.match(r"^\\[([^\\]]+)\\]\\s*(?:#.*)?$", line)
            if not m:
                return None
            parts = [x.strip().strip('"').strip("'") for x in m.group(1).split('.')]
            current = root
            for part in parts:
                current = current.setdefault(part, {})
                if not isinstance(current, dict): return None
            continue
        # key = value
        if '=' not in line:
            return None
        key, value = line.split('=', 1)
        key = key.strip().strip('"').strip("'"); value = value.strip()
