    except ImportError:
        try:
            import tomli as _toml
        except ImportError:
            _toml = None
    if _toml is not None:
        try:
            parsed = _toml.loads(data.decode("utf-8", "replace"))
        except Exception:
            return None
    else:
        parsed = _fallback_toml(data.decode("utf-8", "replace"))
        if parsed is None:
            return None
    if not isinstance(parsed, dict):
        return None
    pkg = parsed.get("package")
